WITH filtered_web_events AS (SELECT *, COALESCE(duration_sec, 0) AS duration_sec_filled FROM web_events WHERE event_type = 'search'), summary AS (SELECT event_type, CASE WHEN duration_sec >= 415 THEN 'high' WHEN duration_sec >= 181 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, SUM(duration_sec_filled) AS total_duration_sec_filled, MIN(event_time) AS min_event_time FROM filtered_web_events GROUP BY event_type, CASE WHEN duration_sec >= 415 THEN 'high' WHEN duration_sec >= 181 THEN 'mid' ELSE 'low' END) SELECT event_type, duration_sec_bucket, total_duration_sec_filled, min_event_time FROM summary WHERE total_duration_sec_filled < 420 ORDER BY duration_sec_bucket;
